#!/usr/bin/env python3
"""Render bounded public-model results from retained final aggregate artifacts."""
import json,re
from pathlib import Path
R=Path(__file__).resolve().parent; P=R/'resumed-0130'; D=R/'publication-draft'
def read(n): return json.loads((P/n).read_text())
def fmt(x,n=2): return 'NA' if x is None else f'{x:.{n}f}'
def table(headers,rows): return '\n'.join(['| '+' | '.join(headers)+' |','|'+'|'.join(['---']*len(headers))+'|']+['| '+' | '.join(map(str,row))+' |' for row in rows])+'\n'
def main():
 m=read('FULL_TEST_METRICS.json');c=read('CSA90_TEST_METRICS.json');q=read('FULL_TEST_QUALITY_DEFAULT.json');f=read('FULL_TEST_QUALITY_FINITE500000.json');cq=read('CSA90_TEST_QUALITY.json');cf=read('CSA90_TEST_QUALITY_FINITE.json'); par=read('FULL_TEST_SOURCE_PARITY.json');cp=read('CSA90_TEST_PAIR_COMPARISONS.json')
 assert m['offered']==21600 and c['offered']==2520
 def source(t,w='morning'):return next(x for x in m['rows'] if x['run_id']==f'test-{w}-{t}')
 names=[('raptor-early-baseline','RAPTOR Early baseline'),('raptor-early-dense','RAPTOR Early dense + walking'),('ea-baseline','EA-CSA baseline'),('ea-combined','EA-CSA dense + walking'),('ultra-control-baseline','Capped ULTRA control baseline'),('ultra-control-dense','Capped ULTRA control dense'),('ultra-subset-dense','Capped ULTRA safe-subset dense'),('mc-dense-labels500000-finite20','McRAPTOR dense 500k + finite20'),('mc-early-dense-labels500000-finite20','McRAPTOR Early dense 500k + finite20'),('trip-based-capped-100m','Capped Trip-Based 100m transfers'),('raptor-baseline','Ordinary RAPTOR baseline'),('raptor-dense','Ordinary RAPTOR dense + walking')]
 body='''# Singapore public-model routing benchmark results

Status: all predeclared heldout runs and aggregate analyses are complete and independent evidence acceptance passed on 2026-10-21. Publication review remains separate. This is a bounded best-measured snapshot, not protocol/global convergence.

## Headline and scope

The separately sealed public-model test ran 76 fresh processes in 19 subcampaigns: 48 primary processes (12 configurations × four windows, 450 requests each) and 28 native-screen processes (four strict-CSA adapters plus three same-query point anchors × four windows, 90 requests each). All 24,120 ordinary offered rows completed. These are configuration executions on shared frozen cohorts, not 24,120 distinct demand queries. Another 24,120 forced-deadline controls are separately labeled; zero warmups. Controls are never included in these ordinary totals or quantiles. No test-triggered source, budget, selector, query filtering or retry was used.

These are finite stop-pair queries against a community frequency-expanded timetable and conservative OSM-derived walking. They are not current official LTA service, live API latency, actual passenger demand, verified physical reachability or an independently exhaustive full-network oracle. See [methodology](METHODOLOGY.md) for native contracts, exact splits, timing exclusions and data assumptions.

There are 27 implemented native entrypoints with deliberately unequal evidence levels. Eight native point-frontier entrypoints have 450 test requests/window (some with baseline/candidate source controls); four strict-CSA entrypoints have 90/window. Auxiliary profile/range/TAD smoke, graph-only CoreCH, unsupported semantics and preprocessing-limited attempts remain separate. OpenTripPlanner is absent. See [evidence levels](EVIDENCE_LEVELS.md), the inventory JSON and retained failure records; a 12-query smoke is not qualified as a 450-query tail study.

## Primary heldout response latency

Morning has 450 requests. The 2D outputs classify 204 as transit, three as all-walk and 243 as valid model-empty. McRAPTOR retains transit alternatives on all 207 nonempty requests, so its transit-conditioned cohort is not identical to the 2D cohort. Never delete model-empty or difficult rows to manufacture a favorable latency.

All rows below completed 450/450. Times are empirical nearest-rank p50/p95/p99 in milliseconds, from common in-process submission through queueing/search/reconstruction/checking/ranking/quality. Input loading, router/checker/quality-index preparation, artifact serialization and transport are excluded and reported separately. Each process serves the whole workload; this is not a new cold process per individual request.

'''
 body+=table(['Native configuration','Offered response p50','p95','p99','Transit-only p50','p95','p99'],[[label]+[fmt(source(t)[k]) for k in ['attempted_response_p50_ms','attempted_response_p95_ms','attempted_response_p99_ms','transit_response_median_ms','transit_response_p95_ms','transit_response_p99_ms']] for t,label in names])
 body+='''\nWithin each frozen native-contract source pair, the dense variants preserve emitted witnesses/status/certificates on all 7,200 offered test comparisons across 16 window-pairs, with zero recorded differences or unknown pairs. This is differential evidence, not full-network completeness proof. Morning p95 decreases by 32.71% for RAPTOR Early, 44.36% for EA-CSA and 43.79% for capped ULTRA control. The richer 3D McRAPTOR row is not an equal-work or equal-quality comparison with a 2D frontier.

Four windows remain separate, not independent population samples. The next table lists offered-response p95; full p50/p95/p99, transit cohorts, failures and resources are in FULL_TEST_METRICS.json.

'''
 body+=table(['Configuration','Morning p95 ms','Midday','Evening','Overnight'],[[label]+[fmt(source(t,w)['attempted_response_p95_ms']) for w in ['morning','midday','evening','overnight']] for t,label in names])
 body+='\n## Startup, allocations and memory are not hidden\n\nMorning measured components below are separate from response. Startup is the sum of instrumented input-load/router/checker/quality-index phases only, not full launch-to-first-byte latency. Hashing, OS-page state, uninstrumented gaps and transport are outside this sum. RSS is sampled whole process-group peak in decimal GB, not a per-query allocation figure; the 7 GiB Go target is soft and no hard dedicated-core/cgroup isolation is claimed. Allocation is measured batch allocation divided by offered attempted requests, not retained memory.\n\n'
 body+=table(['Configuration','Startup phase sum s','First response ms','Router / checker / quality prep s','Query allocation MB/request','Peak RSS GB','Quality-phase p95 ms'],[[label,fmt(source(t)['explicit_startup_phase_sum_s'],3),fmt(source(t)['first_measured_response_ms']),' / '.join(fmt(source(t)[k],3) for k in ['router_preparation_s','checker_preparation_s','quality_preparation_s']),fmt(source(t)['measured_batch_allocated_bytes']/source(t)['attempted']/1e6),fmt(source(t)['sampled_peak_group_rss_bytes']/1e9),fmt(source(t)['attempted_quality_phase_p95_ms'],3)] for t,label in names])
 body+='''\nDense capped ULTRA improves response but increases transient query allocation, so it is not advertised as a memory win. The 100-million retained-transfer operating point for capped Trip-Based retains about 87.8 million actual transfer links and incurs substantial construction/memory costs; its ceiling is not merely a work counter. Cumulative heap/resource snapshots overlap and must not be summed. The finite20 quality phase computes k3+k5 selection and anchor controls together, not top-3-only cost.

## Primary heldout quality

The common observed witness pool is nonempty for 720 of 1,800 requests/configuration, giving 14,400 query × hypothetical-weight slots. All 1,080 model-empty requests/configuration remain in outcome denominators but have no finite preference optimum. Every completed output is independently reconstructed against the finite model. Pool agreement/no observed counterexample is not an exhaustive search proof.

The 20 score hypotheses are elapsed time plus transfer penalties 0/150/300/600/900 seconds and extra-walking weights 0/1/2/4. Walking already contributes to elapsed time. These are not authenticated human preferences or population probabilities. Coverage and regret are relative to this incomplete same-contributor pool. Score-second regret is not necessarily actual travel-time regret.

'''
 qa={x['algorithm']:x for x in q['aggregate_descriptive_only']};fa={x['algorithm']:x for x in f['aggregate_descriptive_only']}
 quality_names=[('raptor','Ordinary RAPTOR'),('raptor_early','RAPTOR Early'),('ea_csa_layered','EA-CSA'),('ultra_transfer_complete_capped','Capped ULTRA control'),('ultra_cap_safe_stay_witness_subset_v1','Capped ULTRA safe subset'),('trip_based_capped','Capped Trip-Based'),('mc_raptor','McRAPTOR'),('mc_raptor_early','McRAPTOR Early')]
 def cov(st):return fmt(st['grid_coverage']*100)+'%'
 body+=table(['Native candidates / default display','Raw coverage','Default top3','Default top5','Max raw / top3 / top5 regret (score-s)'],[[label]+[cov(qa[a]['stages'][k]) for k in ['raw','displayed','displayed_secondary']]+[' / '.join(str(qa[a]['stages'][k]['maximum_pool_relative_regret_score_seconds']) for k in ['raw','displayed','displayed_secondary'])] for a,label in quality_names])
 body+='\nThe separately frozen finite_preferences_v2 selector is optimized to the SAME 20 hypothetical evaluation weights, not a heldout preference model. For both McRAPTOR entrypoints:\n\n'
 body+=table(['Display policy','Top3 coverage','Max top3 regret','Top5 coverage','Max top5 regret'],[[label,cov(v['stages']['displayed']),v['stages']['displayed']['maximum_pool_relative_regret_score_seconds'],cov(v['stages']['displayed_secondary']),v['stages']['displayed_secondary']['maximum_pool_relative_regret_score_seconds']] for label,v in [('Default',qa['mc_raptor_early']),('finite20 (same grid)',fa['mc_raptor_early'])]])
 body+='\nWalking-tie differences explain why arrival/boarding-cap agreement need not imply equal preference quality; EA-CSA and capped Trip-Based are not silently given RAPTOR walking choices. Native3D raw pool coverage100% means no observed-pool regret in this tested grid, not global optimality.\n\n## Strict CSA native90 heldout comparison\n\nThe strict-CSA cohort is every frozen screen-test request, 90/window: 360 per adapter across four windows, with the same90 point-anchor requests. All 2,520 native/anchor rows completed. Single-request versus shared-scan at batch1 agreed on all720 complete paired native outputs. Batch1 tests compatibility, not an assumed batching benefit. Arrival returns one identity-top10 lane; score runs boarding-cap lanes0–4, each k10 with a one-million-label ceiling, and validates/ranks their union. It is not a 2D/3D Pareto contract or necessarily only ten returned identities.\n\nMorning native90 contains35 transit and55 valid-empty outputs per adapter. These empirical p99s have only90 observations and cannot be treated as 450-query or production-tail qualification.\n\n'
 cnames={'csa_arrival_single':'CSA arrival, single-request','csa_arrival_shared':'CSA arrival, shared batch1','csa_score_single':'CSA score, single-request','csa_score_shared':'CSA score, shared batch1','raptor_early':'RAPTOR Early dense anchor','ultra_transfer_complete_capped':'Capped ULTRA dense anchor','mc_raptor_early':'McRAPTOR Early dense finite20 anchor'}
 body+=table(['Native configuration','p50 ms','p95','p99','Startup phase sum s','Peak RSS GB'],[[cnames[v['algorithm']]]+[fmt(v[k]) for k in ['attempted_response_p50_ms','attempted_response_p95_ms','attempted_response_p99_ms']]+[fmt(v['explicit_startup_phase_sum_s'],3),fmt(v['sampled_peak_group_rss_bytes']/1e9)] for v in c['rows'] if '-morning-' in v['run_id']])
 body+='\nIts separate pool is nonempty for121/360 requests, giving2,420 eligible weight slots. This pool/cohort must not be substituted for the full-panel pool.\n\n'
 body+=table(['Native candidates / display','Raw coverage','Default top3','Default top5'],[[cnames[v['algorithm']]]+[cov(v['stages'][k]) for k in ['raw','displayed','displayed_secondary']] for v in cq['aggregate_descriptive_only']])
 v=cf['aggregate_descriptive_only'][0];body+=f"\nThe frozen same-grid finite20 Mc anchor covers{cov(v['stages']['displayed'])} at top3 and{cov(v['stages']['displayed_secondary'])} at top5, with maximum pool-relative regret{v['stages']['displayed']['maximum_pool_relative_regret_score_seconds']}/{v['stages']['displayed_secondary']['maximum_pool_relative_regret_score_seconds']} score-seconds. Large-model evaluation does not independently rederive strict identity-topk; the separate tiny exhaustive/specification source oracles qualify that contract within their tested scope.\n"
 body+='''
## Retained validation, negative and unavailable results

- Primary validation has21,600 complete rows. The original runner stopped after44/48 processes on a relative support-artifact path before four capped Trip-Based processes began. Those four were run in a fresh unchanged-native continuation with only the support path absolute-corrected. Original runner_error, unstarted slots and continuation origins remain distinct; no original completed status was fabricated.
- Original native90 validation has1,438/1,440 CSA rows complete, with one genuine score-single morning deadline and one score-shared midday deadline. The predeclared clean timing replication completed90/90 but does not replace the original89/90. These failures remain in validation quality and outcome denominators. Test completion does not erase validation failures.
- Native batch4/8 includes negative results. Arrival shared-scan was slower; score-shared batch8 completed0/12 offered smoke requests at the common3-second deadline. Cooperative cancellation responses could exceed3seconds. Batch makespan is not divided into per-query latency.
- Larger Mc label ceilings and larger transfer-index budgets are explicit resource-quality operating points, not free source speedups. The small default Mc label budget initially failed some requests; 500k/1m candidates were frozen before heldout testing.
- Legacy bare Trip-Based has an adapter-specific900-second transfer-walking radius and hits its5-million-transfer preparation guard. It was not falsely labeled GTFS-rule unsupported. The successful100m result is the distinct capped600 variant, not a larger-budget bare900 run.
- Legacy FLASH, transfer patterns, scalable TP and TREX reject nonempty GTFS rules. Scoped full-metric FLASH/TREX hit a full-walking-closure guard. Initial malformed fixed-cap TP policies and corrected closure/25m/100m retained-transfer declines are preserved. Ranked TREX's original RSS stop leaves12 unresolved requests; unresolved is not valid-empty or an explicit algorithm decline.
- ProfileCSA/rangeRAPTOR complete48 native tune-smoke profiles each, where one profile covers every integer readiness in a61-time interval. Morning whole-profile medians were about342.79/104.47ms respectively, not divided by61. TAD completes48 one-EA native smoke requests, about39.38ms morning, while reference frontier work is richer. Canonical native ULTRA is unavailable on all48 offered smoke requests because the transfer-rule contract is unsupported; rules were not removed.
- CoreCH is transfer-graph-only, not transit routing. The initial self-only24-anchor smoke is trivial. The frozen117-anchor screen keeps117 whole rows and13,689 target cells per method/window, including105self-only rows and12with positive nonself reachability. Independent raw-edge Bellman-Ford audit found agreement; roughly0.032ms identity versus0.033ms CH row medians did not demonstrate a speedup.
- Rail-entry/exit walking sensitivity is a separate hypothesized model:2,880/2,880 four-window tune rows complete, without merging its witnesses, splits, quality pool or qualification into primary results. More modeled paths do not prove better real-world service.

## Optimization boundary and reproducibility

This is a bounded best-measured source/configuration snapshot. The declared finite convergence protocol, including equal-budget rounds without a new qualifying Pareto improvement, is NOT satisfied; global convergence is also false. Transfer-index compression, alternative preparation data structures, generic walking-metric variants, resource tiers, external preferences and external systems remain unexhausted. Fixed heldout execution order is not randomized; two reversed-order repeated tune blocks provide supporting conditional process observations, not host-noise/population confidence.

The source bundle supplies16 complete baseline-to-candidate/overlay patches, exact offline tree replays, source/build/config hashes, public retrieval checks and portable normalization/walking/workload/evaluator/runner helpers. Baselines are public MIT repositories Ertyoii/transit-routing-bench and Ertyoii/transit-routing-go; the latter's '-go' suffix is required. Raw/complete derived GTFS/OSM/LTA databases, native binaries and credentials are not redistributed. Third-party source rights/notices remain applicable.

Published outcome projections keep every offered status and diagnostic control, objective metrics and witness hashes while withholding full underlying witness legs and replacing execution-local paths. They are not byte-identical raw full passes. Original file hashes remain indexed. Reconstructing omitted witnesses requires authorized retrieval and rerunning the supplied pipeline. Fresh hardware needs new environment/seal bindings; reproducibility does not imply identical timings. No source/config changes or retries may be selected from these exposed test results in this release.
'''
 body=re.sub(r'\b(has|covers|about|all|after|before|complete|with|giving|per|only|first|last|retains|keeps|separate|than|of|on|roughly|contains|and|for|coverage|regret|same|completed|original|common|exceed|its|successful|leaves|completes|frozen|including|versus|supplies)(?=\d)',r'\1 ',body)
 body=re.sub(r'(?<=\d)(?=(?:requests|queries|query|processes|rows|source|paired|single|self|with|seconds|second|ms|GB|MB|million|native|window|validation|complete|transfer|tiny|full|offered|time|same|score|way))', ' ',body)
 body=body.replace('adapter-specific900', 'adapter-specific 900').replace('a61-time', 'a 61-time').replace('by61', 'by 61').replace('capped600', 'capped 600').replace('bare900', 'bare 900').replace('model:2,880', 'model: 2,880').replace('Native3D', 'Native 3D').replace('cap lanes0', 'cap lanes 0').replace('per adapter across four windows', 'per adapter across four windows').replace('at top3', 'at top 3').replace('at top5', 'at top 5')
 D.mkdir(exist_ok=True);(D/'RESULTS.md').write_text(body)
 print('wrote',D/'RESULTS.md',len(body.encode()))
if __name__=='__main__':main()
